from pathlib import Path
import json,subprocess,time
rows=[]
for name,text,expected,count in [('fox_play','小狐狸有点无聊，让它找点乐子。','fox:play',2),('fox_hello','让狐狸认识一下身边的街坊。','fox:greet',2),('fox_solo','小狐狸去打个招呼，其他人不用理它。','fox:greet',2),('departure','让电车带着今天的心情兜一圈。','journey:depart',2),('welcome','在车站好好迎接这位旅客回来。','journey:welcome',2),('cancel','Stop arranging passenger trips, but keep the tram running.','journey:rest',2),('keep','刚才的小狐狸很有趣，保持原样。',None,2)]:
 body={'poem':text,'state':{'weather':'clear','day_phase':'dusk','paper_count':count}}
 cmd=['curl','-sS','--max-time','35','-w','\n%{http_code}','https://echoing-green-api.dongyuanshun.chatgpt.site/api/decision','-H','Origin: https://ashstarry.github.io','-H','Content-Type: application/json','--data-binary','@-']
 started=time.monotonic();raw=subprocess.run(cmd,input=json.dumps(body).encode(),capture_output=True,check=True).stdout.decode();payload,status=raw.rsplit('\n',1);r=json.loads(payload);items=r.get('plan',{}).get('items',[]);passed=status=='200' and (any(i['target']==('animal.garden_fox'if expected.startswith('fox:')else'journey')and i['action']==expected.split(':')[1] for i in items) and not any(i['target']in['occasion','neighborhood']for i in items) if expected else not items);rows.append({'case':name,'request':body,'status':status,'result':r,'pass':passed,'roundtrip_ms':round((time.monotonic()-started)*1000)});Path('outputs/runtime-checkpoint-41/cloud-verification.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2));print(json.dumps({'case':name,'status':status,'pass':passed,'items':[(i['target'],i['action'])for i in items]},ensure_ascii=False))
